insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1004', '透析困難リセット機能', '0', 3, '', '患者情報', 0, '透析困難リセット機能の使用/未使用を設定します。<br>「ON」に設定した場合、患者情報画面で入外区分を入院から外来に切り替えて登録する際に、透析困難情報をリセットします。<br>リセットを行う際は処理前に確認メッセージが表示され、リセットを行うか否か選択することが出来ます。', 4, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1005', 'カード作成機能', '0', 3, '', '利用者マスタ', 1, '利用者マスタでカード作成列の表示/非表示を設定します。<br>「ON」に設定した場合、利用者マスタ画面にカード作成を行うための列を表示します。', 5, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1007', '透析予定日変更時 検査予定変更機能', '3', 4, '[{"id":"1","name":"1:検査依頼を透析予定日に変更"},{"id":"2","name":"2:検査依頼キャンセル"},{"id":"3","name":"3:検査依頼変更なし"}]', '検査依頼', 0, '透析予定日変更時に紐付く検査依頼への処理を設定します。<br>1：変更された透析予定の日付に検査依頼の日付を変更します。<br>また、透析予定がキャンセルされた場合、検査依頼もキャンセルされます。<br>2：検査依頼をキャンセルします。<br>3：検査依頼は変更しません。', 7, 2, current_timestamp, current_timestamp );
