insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1030', 'カードログイン方式', '1', 4, '[{"id":"0","name":"0:無効"},{"id":"1","name":"1:手動"},{"id":"2","name":"2:自動"}]', 'サインイン', 0, 'カードによるサインイン方法を設定します。<br>0:無効：カードでのサインインを無効化します。<br>1:手動：カードを置くとユーザーIDが入力されます。パスワードを手動入力後にサインインボタンを押してサインインします。<br>2:自動：カードを置くだけで自動サインインします。', 26, 2, current_timestamp, current_timestamp );
