insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1034', '体重計選択有効化設定', '0', 4, '[{"id":"0","name":"0:無効"},{"id":"1","name":"1:有効"}]', '体重計・条件送信', 0, '体重測定・条件送信画面での体重計選択の有効/無効を切り替えます。<br>0：無効<br>1：有効<br>【注意】有効化すると、離れた場所や同じ体重計を複数の画面で測定値の受信が可能となります。<br>患者取り違えや重複条件送信などの発生にご注意の上、ご使用ください。', 34, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1035', '空きベッド検索除外予定数', '0', 2, '[{"min":"0",  "max":"9"}]', '患者経過総合ビューア', 0, 'スケジュール登録する際の各ベッドの予定件数しきい値を設定します。<br>対象ベッドの指定したクールと期間に属する予定件数が設定した値以内の場合、対象ベッドを選択可能とします。', 35, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1036', 'パスワードポリシー適用レベル', '4', 4, '[{"id":"1","name":"1:無し"},{"id":"2","name":"2:ポリシー低"},{"id":"3","name":"3:ポリシー中"},{"id":"4","name":"4:ポリシー高"}]', 'アカウント編集', 0, 'サインインパスワードを設定する際のポリシー適用レベルを設定します。第三者から不正にアクセスされるリスクを軽減するための設定です。<br>1:無し：文字数のみ<br>2:ポリシー低：英小文字 と数字を含む<br>3:ポリシー中：次の 4 種類のうち 3 つの文字を使う。・英大文字 (A から Z)・英小文字 (a から z)・10 進数の数字 (0 から 9)・記号 (!、$、#、% など)<br>4:ポリシー高：次の 4 種類の文字を使う。・英大文字 (A から Z)・英小文字 (a から z)・10 進数の数字 (0 から 9)・記号 (!、$、#、% など)', 36, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1037', '２要素認証設定', '0', 4, '[{"id":"0","name":"0:使用しない"},{"id":"1","name":"1:任意使用"},{"id":"2","name":"2:必須使用"}]', 'サインイン', 0, 'ID/パスワードの他に、ソフトトークンなどを使用することでセキュリティを向上させる設定です。<br>0:使用しない：サインイン画面でIDとパスワード入力のみでサインイン<br>1:任意使用・2:必須使用：サインイン画面でIDとパスワード入力に加えて、ワンタイムパスワードを入力してサインイン', 37, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1038', 'パスワード文字数', '8', 2, '[{"min":"4",  "max":"16"}]', 'アカウント編集', 0, 'サインインパスワードの最低文字数を設定します。<br>4文字～16文字の設定が可能です  (初期値:8文字)。', 38, 3, current_timestamp, current_timestamp );
