insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1046', '簡易検索対象条件', '0', 2, '[{"min":"0", "max":"2"}]', '患者検索', 0, '患者簡易検索実行時に対象となる患者を設定します。<br>0：全患者を対象に検索<br>1：死亡患者を除外して検索<br>2：死亡、転出、離脱、移植、拒否・不明を除外して検索', 46, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1047', 'シェーマ機能スタンプ定型文字', E'Ｖ\r\nA\r\n良好\r\n不良\r\n狭窄\r\n閉塞\r\n禁止', 6, '', '患者イベント', 0, 'シェーマ機能のフォントスタンプで選択できる定型文字を設定します。<br>改行することにより複数項目を登録できます。', 47, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1048', '複数端末同時サインイン', '0', 4, '[{"id":"0","name":"0:無効"},{"id":"1","name":"1:有効"}]', 'サインイン', 0, '複数端末で同一アカウント同時ログインの可否を切り替えます。<br>無効にすると、サインイン状態で別端末からサインインをした場合に、サインイン端末が既に存在することを案内し、「現在の端末でサインインしない」か「既にサインインされている端末を強制サインアウトして、現在の端末でサインインする」かを選ぶことができます。', 48, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1049', '導入期加算算定条件', '1', 4, '[{"id":"1", "name":"同月内"},{"id":"2", "name":"日付計算"}]', '患者経過総合ビューア', 0, '加算情報の導入期加算の自動算定方法を切り替えます。<br>同月内：導入開始日に登録された月と「同じ月」（その月の終わりの日まで）の透析日の透析実績に算定する。(例：1/5とした場合、1/5～1/31を加算対象日として算定) <br>日付計算：導入開始日に登録された日付のうち、「次の月の同じ日付の前日」までの透析日の透析実績に算定する。(例：1/5とした場合、1/5～2/4を加算対象日として算定)', 49, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1050', '指示承認設定', '1', 4, '[{"id":"1","name":"医師のみ操作"},{"id":"2","name":"医師リスト"},{"id":"3","name":"全ユーザー"}]', '指示受け・指示承認', 0, '指示承認が可能なユーザーを設定します。 <br>​医師のみ操作：医師のみが編集可能となり、指示承認者は医師のみ選択可能となります<br>​医師リスト：すべてのユーザーが編集可能となり、指示承認者は医師のみ選択可能となります<br>​全ユーザー：すべてのユーザーが編集可能となり、指示承認者にすべてのユーザーが選択可能となります', 50, 2, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1051', '外部警報入力1 ON時メッセージ変更', '外部警報入力1がONになりました', 1, '', '遠隔監視', 0, '装置記録「外部警報入力1」がONになった際のメッセージを設定した文字列に変換して、警報通知メール送信と遠隔監視画面の表示をします。', 51, 3, current_timestamp, current_timestamp );
