insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1059', 'パスワード有効期間（月）', '3', 2, '[{"min":"0",  "max":"999"}]', 'サインイン', 0, 'パスワードの有効期間を月単位で設定します。<br>有効期間が過ぎた後はパスワードの変更が必要となります。<br>設定値を0とした場合、有効期間を無期限とします。', 59, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1060', '過去パスワード再利用禁止（世代）', '3', 2, '[{"min":"0",  "max":"9"}]', 'サインイン', 0, '過去のパスワードを再利用禁止とする設定です。<br>何世代前までの再利用を禁止するか設定します。（最大9世代前まで）<br>設定値を0とした場合、過去のパスワードを再利用禁止しません。', 60, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1061', 'サインイン失敗時のアカウントロック', '1', 4, '[{"id":"0","name":"0:アカウントロックしない"},{"id":"1","name":"1:アカウントロックする"}]', 'サインイン', 0, '連続でサインインに失敗した際にアカウントをロックするか設定します。<br>「アカウントロックする」を選択した場合は、連続サインイン失敗回数が設定したサインイン失敗回数に達した際に、アカウントをロックします。', 61, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1062', 'サインイン失敗許容回数', '5', 2, '[{"min":"1",  "max":"99"}]', 'サインイン', 0, 'サインイン失敗許容回数を設定します。<br>連続サインイン失敗回数が設定回数に達した際に、アカウントをロックします。', 62, 3, current_timestamp, current_timestamp );
insert into sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, system_use_disp, reg_date, up_date)  values ('1063', '2要素認証失敗許容回数', '5', 2, '[{"min":"1",  "max":"99"}]', 'サインイン', 0, '2要素認証失敗許容回数を設定します。<br>2要素認証失敗回数が設定回数に達した際に、再度サインインからやり直しとなります。', 63, 3, current_timestamp, current_timestamp );
